query ThreadsQuery($owner: String!, $name: String!, $number: Int!, $after: String) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      reviewThreads(first: 100, after: $after) {
        pageInfo {
          hasNextPage
          endCursor
        }
        nodes {
          id
          path
          diffSide
          startDiffSide
          line
          startLine
          originalLine
          originalStartLine
          isOutdated
          isResolved
          subjectType
          viewerCanReply
          viewerCanResolve
          viewerCanUnresolve
          first_comment: comments(first: 1) {
            totalCount
            nodes {
              __typename
              ... {
                id
                author {
                  login
                }
                body
                createdAt
                url
                originalCommit {
                  oid
                }
                state
                viewerCanUpdate
                viewerCanDelete
                viewerCanReact
                reactionGroups {
                  content
                  viewerHasReacted
                  reactors {
                    totalCount
                  }
                }
                pullRequestReview {
                  fullDatabaseId
                }
              }
              diffHunk
            }
          }
          comments(last: 99) {
            totalCount
            nodes {
              id
              author {
                login
              }
              body
              createdAt
              url
              originalCommit {
                oid
              }
              state
              viewerCanUpdate
              viewerCanDelete
              viewerCanReact
              reactionGroups {
                content
                viewerHasReacted
                reactors {
                  totalCount
                }
              }
              pullRequestReview {
                fullDatabaseId
              }
            }
          }
        }
      }
    }
  }
}
